import{_ as e,o as t,c as o,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const G=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/AGGREGATE.md","filePath":"manual-zh/AGGREGATE.md","lastUpdated":1785684581000}'),c={name:"manual-zh/AGGREGATE.md"};function p(r,d,E,n,l,A){return t(),o("div",null,[...d[0]||(d[0]=[a(`<h3 id="_12-1-aggregate" tabindex="-1">12.1 AGGREGATE <a class="header-anchor" href="#_12-1-aggregate" aria-label="Permalink to &quot;12.1 AGGREGATE&quot;">​</a></h3><pre><code>AGGREGATE
        [OUTFILE={*,’file_name’,file_handle} [MODE={REPLACE,ADDVARIABLES}]]
        [/MISSING=COLUMNWISE]
        [/PRESORTED]
        [/DOCUMENT]
        [/BREAK=var_list]
        /dest_var[’label’]…=agr_func(src_vars[, args]…)…
</code></pre><p><code>AGGREGATE</code> 将一组个案汇总为单个个案。它把在一个或多个称为 <em>break variables</em>（分组变量）的变量上取值相同的个案划分成组。提供若干函数用于汇总个案内容。</p><p><code>AGGREGATE</code> 的语法由用于控制其行为的子命令（全部可选）组成，其后跟一个或多个目标变量赋值，每个赋值都使用一个聚合函数来定义其计算方式。</p><p>必须排在第一位的 <code>OUTFILE</code> 子命令命名了 <code>AGGREGATE</code> 输出的目标。它可以通过文件名或文件句柄（参见 <a href="./File-Handles">File Handles</a>）指定一个系统文件，通过名称指定一个数据集（参见 <a href="./Datasets">Datasets</a>），或使用 ‘*’ 替换活动数据集。<code>AGGREGATE</code> 将其输出写入该文件。</p><p>仅当 <code>OUTFILE=*</code> 时，可紧接着用值 <code>ADDVARIABLES</code> 或 <code>REPLACE</code> 指定 <code>MODE</code>：</p><ul><li>使用默认值 <code>REPLACE</code> 时，活动数据集被一个新数据集替换，该新数据集只包含分组变量和目标变量。新文件包含的个案数等于分组变量的唯一组合数。</li><li>使用 <code>ADDVARIABLES</code> 时，目标变量被添加到现有活动数据集的变量中。在分组变量上取值组合相同的个案，其目标变量取值也相同。活动数据集中的个案数量保持不变。数据必须已按分组变量排序，也就是说，<code>ADDVARIABLES</code> 隐含 <code>PRESORTED</code>。</li></ul><p>如果省略 <code>OUTFILE</code>，<code>AGGREGATE</code> 的行为如同指定了 <code>OUTFILE=* MODE=ADDVARIABLES</code>。</p><p>默认情况下，<code>AGGREGATE</code> 先按分组变量对数据排序。如果活动数据集已经按分组变量排序或分组，可指定 <code>PRESORTED</code> 以节省时间。使用 <code>MODE=ADDVARIABLES</code> 时，数据必须预先排序。</p><p>指定 <code>DOCUMENT</code> 可将活动数据集中的文档复制到聚合文件（参见 <a href="./DOCUMENT">DOCUMENT</a>）。否则，即使聚合文件替换了活动数据集，聚合文件中也不包含任何文档。</p><p>通常，只要聚合函数所用的非缺失数据足够，<code>AGGREGATE</code> 就会产生非缺失值，即只需一个非缺失值，而对于 <code>SD</code> 和 <code>SD.</code> 聚合函数则需两个非缺失值。指定 <code>/MISSING=COLUMNWISE</code> 可使 <code>AGGREGATE</code> 在输入值中有一个或多个缺失时输出缺失值。</p><p><code>BREAK</code> 子命令可选，但通常会出现。在 <code>BREAK</code> 上列出用于将活动数据集划分为待汇总组的变量。</p><p><code>AGGREGATE</code> 对子命令的顺序有严格要求。<code>OUTFILE</code> 必须排第一，其后是 <code>MISSING</code>。<code>PRESORTED</code> 和 <code>DOCUMENT</code> 在 <code>MISSING</code> 之后，二者顺序任意，其后是 <code>BREAK</code>，再之后是聚合变量说明。</p><p>至少需要一组聚合变量。每组包含一个聚合变量列表、一个等号（‘=’）、一个聚合函数名（见下表），以及括号中的源变量列表。少数聚合函数不接受源变量，有些聚合函数在源变量名之后还需要额外的参数。</p><p><code>AGGREGATE</code> 创建的聚合变量通常没有变量标签、值标签或缺失值。它们的默认打印和写入格式取决于所使用的聚合函数，详见下表。聚合变量的变量标签可在聚合变量列表中的变量名之后指定。</p><p>每组必须具有与聚合变量数量完全相等的源变量。每个聚合变量接收将指定聚合函数应用于相应源变量的结果。</p><p>以下聚合函数只能应用于数值变量：</p><p><code>MEAN(var_name…)</code></p><p>算术平均值。限于数值。默认格式为 F8.2。</p><p><code>MEDIAN(var_name…)</code></p><p>中位数。限于数值。默认格式为 F8.2。</p><p><code>SD(var_name…)</code></p><p>均值的标准差。限于数值。默认格式为 F8.2。</p><p><code>SUM(var_name…)</code></p><p>总和。限于数值。默认格式为 F8.2。</p><p>这些聚合函数可应用于数值变量和字符串变量：</p><p><code>CGT(var_name…, value)</code><code>CLT(var_name…, value)</code><code>CIN(var_name…, low, high)</code><code>COUT(var_name…, low, high)</code></p><p>个案的总权重，分别对应于大于或小于 value，或在闭区间 [low,high] 之内或之外的情形。默认格式为 F5.3。</p><p><code>FGT(var_name…, value)</code><code>FLT(var_name…, value)</code><code>FIN(var_name…, low, high)</code><code>FOUT(var_name…, low, high)</code></p><p>取值中大于或小于 value，或在闭区间 [low,high] 之内或之外的比例。默认格式为 F5.3。</p><p><code>FIRST(var_name…)</code><code>LAST(var_name…)</code></p><p>分别是分组组内第一个或最后一个非缺失值。聚合变量从源变量接收完整的字典信息。<code>AGGREGATE</code>（以及 <code>SORT CASES</code>）执行的排序是稳定排序。这意味着在排序前分组变量取特定值的第一个（或最后一个）个案，在排序后仍是该分组组内的第一个（或最后一个）个案。</p><p><code>MIN(var_name…)</code><code>MAX(var_name…)</code></p><p>分别是最小值或最大值。聚合变量从源变量接收完整的字典信息。</p><p><code>N(var_name…)</code><code>NMISS(var_name…)</code></p><p>分别是非缺失值或缺失值的总权重。若未启用加权，默认格式为 F7.0；若已启用，则为 F8.2（参见 <a href="./WEIGHT">WEIGHT</a>）。</p><p><code>NU(var_name…)</code><code>NUMISS(var_name…)</code></p><p>分别是非缺失值或缺失值的计数，忽略个案权重。默认格式为 F7.0。</p><p><code>PGT(var_name…, value)</code><code>PLT(var_name…, value)</code><code>PIN(var_name…, low, high)</code><code>POUT(var_name…, low, high)</code></p><p>取值中大于或小于 VALUE，或在闭区间 [low,high] 之内或之外的百分比（0 到 100）。默认格式为 F5.1。</p><p>这些聚合函数不接受源变量：</p><p><code>N</code></p><p>聚合形成本组的所有个案的总权重。若未启用加权，默认格式为 F7.0；若已启用，则为 F8.2（参见 <a href="./WEIGHT">WEIGHT</a>）。</p><p><code>NU</code></p><p>聚合形成本组的个案计数，忽略个案权重。默认格式为 F7.0。</p><p>聚合函数按照内部字符编码比较字符串值。在大多数现代计算机上，这是 ASCII 或其超集。</p><p>上面列出的聚合函数在计算中会排除所有用户缺失值。要包含用户缺失值，可在函数名末尾加一个句点（‘.’）。（例如 ‘SUM.’）。（注意：若将此类函数作为一行中的最后一个记号，该句点会被解释为该命令的结束符。）</p><p><code>AGGREGATE</code> 会忽略并取消当前的 <code>SPLIT FILE</code> 设置（参见 <a href="./SPLIT-FILE">SPLIT FILE</a>）。</p><h4 id="_12-1-1-聚合示例" tabindex="-1">12.1.1 聚合示例 <a class="header-anchor" href="#_12-1-1-聚合示例" aria-label="Permalink to &quot;12.1.1 聚合示例&quot;">​</a></h4><p>数据集 personnel.sav 提供了许多人的职业和薪水。然而在许多场合，如此详细的信息并无太大意义，但各个职业的聚合统计量往往是有用的。在示例 12.1 中，<code>AGGREGATE</code> 命令用于计算每个职业的均值、中位数和标准差。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET FILE=&quot;personnel.sav&quot;. AGGREGATE OUTFILE=* MODE=REPLACE         /BREAK=occupation         /occ_mean_salary=MEAN(salary)         /occ_median_salary=MEDIAN(salary)         /occ_std_dev_salary=SD(salary). LIST.</span></span></code></pre></div><p><strong>示例 12.1：</strong> 从 personnel.sav 文件计算聚合统计量</p><p>由于我们选择了 ‘MODE=REPLACE’ 选项，在结果 12.1 中不再存在单个人员的个案。每个聚合值已被单个个案所取代。</p><table tabindex="0"><thead><tr><th>occupation</th><th>occ_mean_salary</th><th>occ_median_salary</th><th>occ_std_dev_salary</th></tr></thead><tbody><tr><td>Artist</td><td>37836.18</td><td>34712.50</td><td>7631.48</td></tr><tr><td>Baker</td><td>45075.20</td><td>45075.20</td><td>4411.21</td></tr><tr><td>Barrister</td><td>39504.00</td><td>39504.00</td><td>.</td></tr><tr><td>Carpenter</td><td>39349.11</td><td>36190.04</td><td>7453.40</td></tr><tr><td>Cleaner</td><td>41142.50</td><td>39647.49</td><td>14378.98</td></tr><tr><td>Cook</td><td>40357.79</td><td>43194.00</td><td>11064.51</td></tr><tr><td>Manager</td><td>46452.14</td><td>45657.56</td><td>6901.69</td></tr><tr><td>Mathematician</td><td>34531.06</td><td>34763.06</td><td>5267.68</td></tr><tr><td>Painter</td><td>45063.55</td><td>45063.55</td><td>15159.67</td></tr><tr><td>Payload Specialist</td><td>34355.72</td><td>34355.72</td><td>.</td></tr><tr><td>Plumber</td><td>40413.91</td><td>40410.00</td><td>4726.05</td></tr><tr><td>Scientist</td><td>36687.07</td><td>36803.83</td><td>10873.54</td></tr><tr><td>Scrientist</td><td>42530.65</td><td>42530.65</td><td>.</td></tr><tr><td>Tailor</td><td>34586.79</td><td>34586.79</td><td>3728.98</td></tr></tbody></table><p><strong>结果 12.1：</strong> 每个 <strong>occupation</strong>（职业）的聚合均值、中位数和标准差</p><p>注意，标准差的某些值为空。这是因为相应职业只有一个个案。</p>`,56)])])}const i=e(c,[["render",p]]);export{G as __pageData,i as default};
